public class AVLTreeNode { public int Key; public AVLTreeNode Left; public AVLTreeNode Right; public int Height; public AVLTreeNode(int key) { Key = key; Height = 1; } } public class AVLTree { private AVLTreeNode root; public void Insert(int key) { root = Insert(root, key); } private AVLTreeNode Insert(AVLTreeNode node, int key) { if (node == null) return new AVLTreeNode(key); if (key < node.Key) node.Left = Insert(node.Left, key); else if (key > node.Key) node.Right = Insert(node.Right, key); else return node; node.Height = 1 + Math.Max(GetHeight(node.Left), GetHeight(node.Right)); return Balance(node); } public void Delete(int key) { root = Delete(root, key); } private AVLTreeNode Delete(AVLTreeNode node, int key) { if (node == null) return node; if (key < node.Key) node.Left = Delete(node.Left, key); else if (key > node.Key) node.Right = Delete(node.Right, key); else { if (node.Left == null || node.Right == null) { AVLTreeNode temp = node.Left ?? node.Right; if (temp == null) return null; else return temp; } AVLTreeNode tempNode = GetMinValueNode(node.Right); node.Key = tempNode.Key; node.Right = Delete(node.Right, tempNode.Key); } node.Height = 1 + Math.Max(GetHeight(node.Left), GetHeight(node.Right)); return Balance(node); } private AVLTreeNode Balance(AVLTreeNode node) { int balance = GetBalance(node); if (balance > 1) { if (GetBalance(node.Left) < 0) node.Left = RotateLeft(node.Left); return RotateRight(node); } if (balance < -1) { if (GetBalance(node.Right) > 0) node.Right = RotateRight(node.Right); return RotateLeft(node); } return node; } private AVLTreeNode RotateRight(AVLTreeNode y) { AVLTreeNode x = y.Left; AVLTreeNode T2 = x.Right; x.Right = y; y.Left = T2; y.Height = 1 + Math.Max(GetHeight(y.Left), GetHeight(y.Right)); x.Height = 1 + Math.Max(GetHeight(x.Left), GetHeight(x.Right)); return x; } private AVLTreeNode RotateLeft(AVLTreeNode x) { AVLTreeNode y = x.Right; AVLTreeNode T2 = y.Left; y.Left = x; x.Right = T2; x.Height = 1 + Math.Max(GetHeight(x.Left), GetHeight(x.Right)); y.Height = 1 + Math.Max(GetHeight(y.Left), GetHeight(y.Right)); return y; } private int GetHeight(AVLTreeNode node) { return node == null ? 0 : node.Height; } private int GetBalance(AVLTreeNode node) { return node == null ? 0 : GetHeight(node.Left) - GetHeight(node.Right); } private AVLTreeNode GetMinValueNode(AVLTreeNode node) { AVLTreeNode current = node; while (current.Left != null) current = current.Left; return current; } public void InOrderTraversal() { InOrderTraversal(root); } private void InOrderTraversal(AVLTreeNode node) { if (node != null) { InOrderTraversal(node.Left); Console.Write(node.Key + " "); InOrderTraversal(node.Right); } } public bool IsBalanced() { return IsBalanced(root); } private bool IsBalanced(AVLTreeNode node) { if (node == null) return true; int balance = GetBalance(node); return (balance > -2 && balance < 2) && IsBalanced(node.Left) && IsBalanced(node.Right); } }